sp_widget.client_script:
api.controller=function($scope,spUtil, nowAttachmentHandler,$location){
 var c=this;
 c.post=function(){
   if(!c.comment)return;
   c.data.comment=c.comment;
   c.server.update().then(function(response){
		 //spUtil.addInfoMessage(JSON.stringify(response));
      c.data=response;
		 	c.data.id=response.sys_id;
      c.comment='';
		// $scope.update();
   });
 };

	c.goBack = function() {
        window.history.back();
    };


	$scope.attachmentHandler = new nowAttachmentHandler(
    setAttachments,
    appendError
);
	c.escalatereason = c.data.dispute.escalated_reason;
	c.escalateDispute = function () {

    if (!c.escalatereason) {
        spUtil.addErrorMessage("Please enter escalation reason.");
        return;
    }

		c.data.reason = c.escalatereason;
    c.data.action = "escalate";


    c.server.update().then(function(response) {

        spUtil.addInfoMessage("Dispute escalated successfully.");

        c.showEscalation = false;

        c.escalatereason = c.data.dispute.escalated_reason;

      spUtil.update($scope);

    });

};

function setAttachments(attachments) {
    c.attachments = attachments;
}

function appendError(error) {
    spUtil.addErrorMessage(error.msg);
}


	$scope.attachmentHandler.setParams(
    "x_ctans_incentnow_incentiq_dispute",
    c.data.id,
    1024 * 1024 * 50   // 50 MB
);

};

sp_widget.css:
/* ==========================================================
   GLOBAL
========================================================== */

body{
    background:#f5f7fa;
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}

*{
    box-sizing:border-box;
}

.page-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    margin-bottom: 16px;
}



/* ==========================================================
   BACK BUTTON
========================================================== */

.admin-back-btn{
    display:flex;
    align-items:center;
    justify-content:center;
    width:42px;
    height:42px;
    border-radius:50%;
    border:1px solid #d0d5dd;
    background:#fff;
    cursor:pointer;
    transition:.2s;
  flex-shrink: 0;
}


.admin-back-btn:hover{
    background:#f8f9fc;
    border-color:#98a2b3;
}

/* ==========================================================
   PAGE
========================================================== */

.dispute-container{

    max-width:1200px;
    margin:auto;
    padding-bottom:40px;
}

.content-layout{

    display:grid;
    grid-template-columns:2fr 360px;
    gap:24px;
    align-items:start;
}

.description-divider{
    height:1px;
    background:#eaecf0;
    margin:20px 0;
}

/* ==========================================================
   CARD
========================================================== */

.card{

    background:#fff;

    border:1px solid #eaecf0;

    border-radius:14px;

    padding:24px;

    margin-bottom:24px;

    box-shadow:0 2px 10px rgba(16,24,40,.05);

    transition:.25s;
}

.card:hover{

    box-shadow:0 10px 24px rgba(16,24,40,.08);
}

/* ==========================================================
   HEADER
========================================================== */

.dispute-header-card{

    margin-bottom:25px;

    background:linear-gradient(180deg,#fff,#fafbfc);
}

.dispute-number{

    display:flex;

    align-items:center;

    gap:15px;

    flex-wrap:wrap;

    font-size:30px;

    font-weight:700;

    color:#101828;
}

.dispute-title{

    margin:15px 0 10px;

    font-size:28px;

    font-weight:600;

    color:#344054;
}

.header-meta{

    display:flex;

    gap:20px;

    flex-wrap:wrap;

    color:#667085;

    font-size:14px;
}

.header-meta i{

    margin-right:6px;
}

/* ==========================================================
   BADGE
========================================================== */

.badge{

    padding:8px 16px;

    border-radius:999px;

    font-size:12px;

    font-weight:600;
}

.badge-primary{

    background:#eef4ff;

    color:#175cd3;
}

.badge-success{

    background:#ecfdf3;

    color:#027a48;
}

.badge-warning{

    background:#fff7e6;

    color:#b54708;
}

.badge-danger{

    background:#fef3f2;

    color:#d92d20;
}

/* ==========================================================
   SECTION
========================================================== */

.section-title{

    display:flex;

    align-items:center;

    gap:10px;

    font-size:18px;

    font-weight:600;

    color:#101828;

    margin-bottom:20px;

    padding-bottom:12px;

    border-bottom:1px solid #eaecf0;
}

.section-title i{

    color:#000;
}

/* ==========================================================
   DESCRIPTION
========================================================== */

.description-box{

    background:#f9fafb;

    border:1px solid #eaecf0;

    border-radius:12px;

    padding:22px;

    color:#344054;

    line-height:1.8;

    white-space:pre-wrap;
}

.short-description-box
{
  background:#f9fafb;

    border:1px solid #eaecf0;

    border-radius:12px;

    padding:10px;

    color:#344054;

    line-height:1;

    white-space:pre-wrap;
}
.badge-info {
    background: #f4f3ff;
    color: #6941c6;
}
/* ==========================================================
   SIDEBAR
========================================================== */

.info-card{

    border:1px solid #eaecf0;

    border-radius:12px;

    padding:16px;

    margin-bottom:14px;

    transition:.2s;
}

.info-card:hover{

    transform:translateY(-2px);

    border-color:#d0d5dd;
}

.info-label{

    font-size:11px;

    font-weight:700;

    text-transform:uppercase;

    letter-spacing:.08em;

    color:#98a2b3;

    margin-bottom:8px;
}

.info-value{

    font-size:15px;

    font-weight:600;

    color:#101828;

    word-break:break-word;
}

/* ==========================================================
   COMMENT BOX
========================================================== */

.comment-box label{

    display:block;

    margin-bottom:10px;

    font-weight:600;

    color:#344054;
}

.comment-box textarea{

    width:100%;

    resize:none;

    min-height:140px;

    padding:15px;

    border-radius:12px;

    border:1px solid #d0d5dd;

    transition:.2s;
}

.comment-box textarea:focus{

    outline:none;

    border-color:#000;

    box-shadow:0 0 0 4px rgba(0,0,0,.08);
}

.comment-actions{

    display:flex;

    justify-content:flex-end;

    align-items:center;

    gap:12px;

    margin-top:18px;
}

/* ==========================================================
   BUTTON
========================================================== */

.btn-post{

    background:#000;

    color:#fff;

    border:none;

    border-radius:10px;

    padding:11px 24px;

    font-weight:600;

    transition:.25s;

  margin-top: 10px;
}

.btn-post:hover{

    background:#fff;
  	color: #000;
  border: 1px solid #0b5fff;
}

.btn-post i{

    margin-right:8px;
}

/* ==========================================================
   ACTIVITY
========================================================== */

.activity-stream{

    margin-top:25px;

    border-top:1px solid #eaecf0;

    padding-top:20px;
}

/* ==========================================================
   RESPONSIVE
========================================================== */

@media(max-width:992px){

.content-layout{

    grid-template-columns:1fr;
}

.content-sidebar{

    order:-1;
}

}

@media(max-width:768px){

.dispute-number{

    font-size:24px;
}

.dispute-title{

    font-size:22px;
}

.header-meta{

    flex-direction:column;

    gap:8px;
}

.comment-actions{

    flex-direction:column;

    align-items:stretch;
}

.btn-post{

    width:100%;
}

}

/* ==========================================================
   ATTACHMENT BUTTON
========================================================== */

sp-attachment-button{

    display:flex;

    align-items:center;
}

sp-attachment-button button{

    border-radius:10px !important;
}

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */


		data.access=false;
		data.id=$sp.getParameter('sys_id');
		var grDispute=new GlideRecordSecure('x_ctans_incentnow_incentiq_dispute');
		grDispute.addQuery('sys_id',data.id);
		//var qc=gr.addQuery('raised_for',gs.getUserID());
		//qc.addOrCondition('assigned_to',gs.getUserID());
		grDispute.query();

		if(!grDispute.next()) return;
		data.access=true;
		if(input && input.comment){
			grDispute.comments=input.comment;
			grDispute.update();

			data.sysid=data.id;
		}

		if (input && input.action == "escalate") {

    grDispute.setValue("escalated", true);
    grDispute.setValue("escalated_reason", input.reason);


    grDispute.update();

    data.success = true;
}

		data.dispute={
		 	number:grDispute.getValue('number'),
		 	state:grDispute.getDisplayValue('state'),
			stateval: grDispute.getValue('state'),
		 	priority:grDispute.getDisplayValue('priority'),
		 	raised_for:grDispute.getDisplayValue('raised_for'),
			short_description:grDispute.getDisplayValue('short_description'),
		 	description:grDispute.getDisplayValue('description'),
			created:grDispute.getDisplayValue('sys_created_on'),
			assigned_to:grDispute.getDisplayValue('assigned_to'),
			escalated: grDispute.getValue('escalated'),
			escalated_reason: grDispute.getDisplayValue('escalated_reason')
		};




		if(data.dispute.stateval=="6" || data.dispute.stateval=="7" || data.dispute.stateval=="8")
			{
				data.allFieldReadonly=true;
			}
	else
		{
			data.allFieldReadonly=false;
		}

		data.comments=[];
		var jf=new GlideRecordSecure('sys_journal_field');
		jf.addQuery('element_id',grDispute.getUniqueValue());
		jf.addQuery('element','comments');
		jf.orderByDesc('sys_created_on');
		jf.query();
		while(jf.next()){
			var name = jf.getDisplayValue("sys_created_by");

    var initials = "";

    if (name) {
        var parts = name.trim().split(" ");

        if (parts.length == 1) {
            initials = parts[0].substring(0, 1).toUpperCase();
        } else {
            initials =
                parts[0].substring(0, 1).toUpperCase() +
                parts[parts.length - 1].substring(0, 1).toUpperCase();
        }
    }

		 data.comments.push({
			user:jf.getDisplayValue('sys_created_by'),
			date:jf.getDisplayValue('sys_created_on'),
			comment:jf.getValue('value'),
			 initials: initials,

		 });
		}

	data.activityWidget = $sp.getWidget('dispute_conversations', {
    table: 'x_ctans_incentnow_incentiq_dispute',
    sys_id: data.id
});




})();
